-- Robotics/Embedded/IoT pathway ("Vector Division") Act 12 -- "Memory &
-- Storage" content, under world-vec-memory-and-storage (already inserted
-- separately, act-vec-2, index 11). 1 campaign, 2 operations, 12 missions
-- (11 lessons + boss), following the same campaigns -> operations ->
-- missions -> dialogue -> objectives -> challenges -> hints pattern as
-- every prior Act. No new ChallengeType needed -- reuses story_dialogue,
-- investigation, multiple_choice, interactive_diagram, drag_and_drop,
-- browser_simulation (generic console fallback) and boss_encounter.
--
-- With the RTOS running reliably (Act 11), Vector Division tries to make
-- the reactor arm's retuned gains and the door's calibration data survive
-- a power cycle -- and one board simply refuses to remember anything
-- after its next reset. The boss mission ("Flash Exhaustion") lands on
-- the same firmware habit already caught in Act 5's heap leak (writing
-- something on every pass, never bounded), except this time it silently
-- exhausted a flash sector's finite write-erase cycle rating instead of
-- RAM. It closes on the requirement that sets up Act 13: firmware that
-- finally remembers correctly is still firmware sitting on a bench --
-- getting it onto every live device safely needs a real boot and update
-- path, not hand-flashing one board at a time.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-memory-and-storage', 'world-vec-memory-and-storage', 'memory-and-storage', '2G - Memory & Storage', 'Learn the vocabulary of persistent memory -- flash, RAM, EEPROM concepts, nonvolatile storage, filesystem concepts, wear and endurance, ring buffers, persistent configuration, logging on constrained devices, boot state and crash dumps -- while Vector Division tries to make the reactor arm''s retuned gains and the door''s calibration survive a power cycle, and one board simply forgets everything.', 12);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-memory-and-storage-1', 'campaign-vec-memory-and-storage', 'what-survives-a-reset', 'What Survives a Reset', 'Flash, RAM, EEPROM concepts, nonvolatile storage, filesystem concepts and wear and endurance -- the vocabulary of what actually holds data once the power cuts out.', 1),
  ('operation-vec-memory-and-storage-2', 'campaign-vec-memory-and-storage', 'the-sector-that-wore-out', 'The Sector That Wore Out', 'Ring buffers, persistent configuration, logging on constrained devices, boot state and crash dumps -- the practices that decide whether a flash sector survives its own firmware.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-memory-and-storage-01', 'world-vec-memory-and-storage', 'campaign-vec-memory-and-storage', 'operation-vec-memory-and-storage-1', 'flash', 'Flash Memory', 'With the RTOS running reliably, Vector Division tries to make the reactor arm''s freshly retuned gains and the door''s calibration data survive a power cycle -- and one board comes back from its next reset with nothing. Tomas Vey starts with the one question that decides everything else: what kind of memory was ever supposed to hold that data in the first place.', 'beginner', ARRAY['imani','tomas','byte'], null, null, '{"type":"simulation","simulationId":"flash-sim"}'::jsonb, '{"xp":190,"credits":25}'::jsonb, false, 1),
  ('mission-vec-memory-and-storage-02', 'world-vec-memory-and-storage', 'campaign-vec-memory-and-storage', 'operation-vec-memory-and-storage-1', 'ram', 'RAM', 'Byte''s first instinct is to just keep the values in RAM and never lose them. Tomas needs the player to explain, precisely, why that plan was broken before anyone even wrote a line of code.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-memory-and-storage-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"ram-sim"}'::jsonb, '{"xp":190,"credits":30}'::jsonb, false, 2),
  ('mission-vec-memory-and-storage-03', 'world-vec-memory-and-storage', 'campaign-vec-memory-and-storage', 'operation-vec-memory-and-storage-1', 'eeprom-concepts', 'EEPROM Concepts', 'Not every persistent memory works like flash. EEPROM keeps data without power too, but it forgets and remembers one byte at a time instead of one whole sector -- and knowing the difference is about to matter.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-memory-and-storage-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"eeprom-concepts-sim"}'::jsonb, '{"xp":200,"credits":30}'::jsonb, false, 3),
  ('mission-vec-memory-and-storage-04', 'world-vec-memory-and-storage', 'campaign-vec-memory-and-storage', 'operation-vec-memory-and-storage-1', 'nonvolatile-storage', 'Nonvolatile Storage', 'Flash and EEPROM are not the whole category. Nonvolatile storage is the umbrella term for anything that survives with no power at all, and this board''s datasheet finally says, in writing, which technology it actually uses.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-memory-and-storage-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"nonvolatile-storage-sim"}'::jsonb, '{"xp":200,"credits":30}'::jsonb, false, 4),
  ('mission-vec-memory-and-storage-05', 'world-vec-memory-and-storage', 'campaign-vec-memory-and-storage', 'operation-vec-memory-and-storage-1', 'filesystem-concepts', 'Filesystem Concepts', 'Raw flash is just a grid of addresses. A filesystem is the layer that turns those addresses into something a firmware engineer can reason about -- and this board''s original firmware never had one.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-memory-and-storage-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"filesystem-concepts-sim"}'::jsonb, '{"xp":210,"credits":35}'::jsonb, false, 5),
  ('mission-vec-memory-and-storage-06', 'world-vec-memory-and-storage', 'campaign-vec-memory-and-storage', 'operation-vec-memory-and-storage-1', 'wear-and-endurance', 'Wear and Endurance', 'Every flash sector is rated for a finite number of write-erase cycles before it simply stops holding a charge reliably. Tomas has seen this exact failure shape before -- on a different resource, in a much earlier Act.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-memory-and-storage-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"wear-and-endurance-sim"}'::jsonb, '{"xp":210,"credits":35}'::jsonb, false, 6),
  ('mission-vec-memory-and-storage-07', 'world-vec-memory-and-storage', 'campaign-vec-memory-and-storage', 'operation-vec-memory-and-storage-2', 'ring-buffers', 'Ring Buffers', 'A ring buffer never grows without bound. It just wraps back to the beginning and reuses its own space -- which makes it Vector Division''s first real candidate for keeping flash writes under control.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-memory-and-storage-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"ring-buffers-sim"}'::jsonb, '{"xp":220,"credits":35}'::jsonb, false, 7),
  ('mission-vec-memory-and-storage-08', 'world-vec-memory-and-storage', 'campaign-vec-memory-and-storage', 'operation-vec-memory-and-storage-2', 'persistent-configuration', 'Persistent Configuration', 'Somewhere on this board is a fixed few kilobytes reserved for exactly one job: holding the reactor arm''s gains and the door''s calibration across a reset. How that region gets written matters as much as what it stores.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-memory-and-storage-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"persistent-configuration-sim"}'::jsonb, '{"xp":220,"credits":40}'::jsonb, false, 8),
  ('mission-vec-memory-and-storage-09', 'world-vec-memory-and-storage', 'campaign-vec-memory-and-storage', 'operation-vec-memory-and-storage-2', 'logging-on-constrained-devices', 'Logging on Constrained Devices', 'The RTOS''s own telemetry logging, built back in Act 11, already writes to flash constantly. Byte wants to know why that logging is not failing the same way the configuration save is.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-memory-and-storage-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"logging-on-constrained-devices-sim"}'::jsonb, '{"xp":230,"credits":40}'::jsonb, false, 9),
  ('mission-vec-memory-and-storage-10', 'world-vec-memory-and-storage', 'campaign-vec-memory-and-storage', 'operation-vec-memory-and-storage-2', 'boot-state', 'Boot State', 'Every boot starts the same way: read the saved configuration, check that it is actually valid, and only then trust it. This board''s boot sequence is about to fail that check for the first time.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-memory-and-storage-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"boot-state-sim"}'::jsonb, '{"xp":230,"credits":40}'::jsonb, false, 10),
  ('mission-vec-memory-and-storage-11', 'world-vec-memory-and-storage', 'campaign-vec-memory-and-storage', 'operation-vec-memory-and-storage-2', 'crash-dumps', 'Crash Dumps', 'When a device crashes, the one thing worth saving is exactly what it was doing at the moment it died -- but writing that record safely, after everything else has already gone wrong, is its own discipline.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-memory-and-storage-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"crash-dumps-sim"}'::jsonb, '{"xp":240,"credits":45}'::jsonb, false, 11),
  ('mission-vec-memory-and-storage-12', 'world-vec-memory-and-storage', 'campaign-vec-memory-and-storage', 'operation-vec-memory-and-storage-2', 'flash-exhaustion', 'Flash Exhaustion', 'One board refuses to remember anything after its next reset. Everything this Act taught, aimed at one sector: not to replace it and move on, but to prove exactly why it died and make sure nothing else on Vector Division''s bench dies the same way.', 'boss', ARRAY['imani','tomas','byte'], '{"requiredMissionIds":["mission-vec-memory-and-storage-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"flash-exhaustion-boss-sim"}'::jsonb, '{"xp":950,"credits":200,"badgeIds":["flash-exhaustion"],"skillXp":{"robotics_fundamentals":120}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-memory-and-storage-01', 1, 'imani', 'The RTOS holds now. Reactor arm and door both run their control loops correctly, in order, under real scheduling. So we tried the obvious next step -- power-cycle both boards and see if they remember their own settings. The reactor arm''s board came back perfectly. The door''s board came back with nothing.'),
  ('mission-vec-memory-and-storage-01', 2, 'tomas', 'Tomas Vey. "Nothing" is not vague to me -- it is a specific, answerable question. Before I touch a single register, I want to know what kind of memory was ever supposed to hold that configuration across a reset in the first place.'),
  ('mission-vec-memory-and-storage-01', 3, 'tomas', 'Most of what a running program touches lives in RAM, and RAM forgets everything the instant power drops. Anything meant to survive a reset has to live somewhere else -- in flash, memory built specifically to hold its contents with no power applied at all.'),
  ('mission-vec-memory-and-storage-01', 4, 'tomas', 'Flash does not read and write like RAM either. You can write into an already-erased page freely. But you can only erase in much larger chunks called sectors, and erasing is the only way to flip a bit back from a zero to a one.'),
  ('mission-vec-memory-and-storage-01', 5, 'byte', 'The firmware just calls a function named something like save_config() and assumes it works every time, forever. Nobody on the original team seems to have asked what "forever" actually costs a real chip.'),

  ('mission-vec-memory-and-storage-02', 1, 'byte', 'Simplest possible fix: just keep the gains and the calibration sitting in RAM and never let the board reset at all.'),
  ('mission-vec-memory-and-storage-02', 2, 'tomas', 'Explain to me how that survives a power cycle. RAM holds a charge only as long as it is powered. Cut the power, even for an instant, and every value in it is gone -- not corrupted, not scrambled, simply gone.'),
  ('mission-vec-memory-and-storage-02', 3, 'tomas', 'That is what "volatile" means here. RAM is fast and byte-addressable and completely honest about its one condition: it only remembers while it is holding power. Whatever we build has to live somewhere that condition does not apply.'),

  ('mission-vec-memory-and-storage-03', 1, 'tomas', 'Flash is not the only nonvolatile option. EEPROM keeps data with no power too, and it does something flash cannot -- it lets you erase and rewrite a single byte at a time instead of an entire sector.'),
  ('mission-vec-memory-and-storage-03', 2, 'tomas', 'The trade is size and speed. EEPROM chips are usually smaller and slower than flash, and cost more per byte. Engineers pick EEPROM for a handful of settings that change constantly, and flash for larger, more static data.'),

  ('mission-vec-memory-and-storage-04', 1, 'tomas', '"Nonvolatile" is not a specific technology. It is the umbrella term for any storage that keeps its contents with no power at all -- flash, EEPROM, and a few older technologies besides. "Volatile" is the opposite: RAM, caches, CPU registers, anything that needs continuous power to remember.'),
  ('mission-vec-memory-and-storage-04', 2, 'byte', 'I finally found this board''s actual datasheet in the facilities archive instead of guessing from behavior. It confirms exactly one nonvolatile technology present on this board.'),
  ('mission-vec-memory-and-storage-04', 3, 'tomas', 'Good. From here on we stop saying "the memory" and start saying its real name.'),

  ('mission-vec-memory-and-storage-05', 1, 'tomas', 'On a desktop, a filesystem hides the raw disk from you -- you save a file by name, not by disk sector. Embedded flash can run the same way, through a small filesystem layer that tracks which physical addresses are free, used, or worn.'),
  ('mission-vec-memory-and-storage-05', 2, 'tomas', 'This board''s original firmware never had one. It writes straight to a hardcoded flash address, the same way every single time, with nothing tracking where it has already written or how many times.'),

  ('mission-vec-memory-and-storage-06', 1, 'tomas', 'Every flash sector has an endurance rating -- a maximum number of write-erase cycles the manufacturer guarantees before it stops holding a charge reliably. Typical ratings run somewhere between ten thousand and a few hundred thousand cycles, and past that the count stops being a guarantee at all.'),
  ('mission-vec-memory-and-storage-06', 2, 'tomas', 'Past that limit, a bit that should hold a zero starts drifting back to a one on its own, or refuses to flip at all. That is not corruption from a software bug. That is the physical material simply wearing out.'),
  ('mission-vec-memory-and-storage-06', 3, 'byte', 'I have seen this exact shape of failure before -- Act 5, the reactor telemetry service. An unbounded allocation on every single main-loop pass, quietly consuming a finite resource until it ran out.'),
  ('mission-vec-memory-and-storage-06', 4, 'tomas', 'Same habit, different resource. There it was heap memory. If whatever writes this board''s configuration fires on every pass too, instead of only when something actually changed, it is spending the sector''s finite lifespan exactly the same careless way.'),

  ('mission-vec-memory-and-storage-07', 1, 'tomas', 'A ring buffer is a fixed-size region with a write pointer that always advances forward and wraps back to the start once it reaches the end. It never grows. It just keeps reusing its own space, oldest entry first.'),
  ('mission-vec-memory-and-storage-07', 2, 'tomas', 'For flash specifically, that wrap-around is not just about bounding memory. Writing to a new location each time instead of the same one over and over spreads wear across several places instead of exhausting a single sector alone.'),

  ('mission-vec-memory-and-storage-08', 1, 'byte', 'I pulled the region this board reserves for persistent configuration. It is a fixed few kilobytes, and every save this firmware has ever performed writes to the exact same starting address inside it.'),
  ('mission-vec-memory-and-storage-08', 2, 'tomas', 'Same address, every single save, whether the gains actually changed or not. That is the naive approach -- functionally correct, and it treats the sector''s finite lifespan as if it did not exist.'),
  ('mission-vec-memory-and-storage-08', 3, 'tomas', 'The better approach saves only on an actual change, and rotates across multiple slots in that reserved region instead of hammering one fixed address -- close to what a ring buffer already does.'),

  ('mission-vec-memory-and-storage-09', 1, 'byte', 'The RTOS telemetry logging from Act 11 also writes to flash constantly, and it is not failing. If flash wear were simply unavoidable, I would expect it to be dying too.'),
  ('mission-vec-memory-and-storage-09', 2, 'tomas', 'Look at how it writes, not just that it writes. Good logging on a constrained device batches entries and writes in a circular pattern across a dedicated log region -- it treats flash endurance as a budget from the very first line of its design.'),
  ('mission-vec-memory-and-storage-09', 3, 'tomas', 'The configuration save routine was never designed with that budget in mind at all. It was written once, for a board where nobody expected it to still be running years later.'),

  ('mission-vec-memory-and-storage-10', 1, 'tomas', 'Every boot follows the same order: power on, read the saved configuration out of its reserved sector, check a checksum to confirm it is actually valid, and only then load it. Anything that fails the checksum falls back to safe defaults instead of trusting garbage.'),
  ('mission-vec-memory-and-storage-10', 2, 'tomas', 'This board is not falling back to defaults. It is failing the checksum and then reporting nothing readable at all -- which is a different, worse failure than a simple corrupted value.'),

  ('mission-vec-memory-and-storage-11', 1, 'tomas', 'A crash dump is a record of exactly what a device was doing the instant before it failed, written to nonvolatile memory so it survives the very reset that follows. Get it wrong and you either lose the record or corrupt something else trying to save it.'),
  ('mission-vec-memory-and-storage-11', 2, 'byte', 'This board actually has a small crash-dump region, separate from the configuration sector. On the last reset it managed to write one entry before going silent.'),
  ('mission-vec-memory-and-storage-11', 3, 'tomas', 'Then that entry is the most honest witness we have. Whatever it says about that write, believe it over any guess we have made so far.'),

  ('mission-vec-memory-and-storage-12', 1, 'imani', 'One board, completely blank after its next reset. Everything this Act taught you is about to answer one question: not how to patch it, but exactly why it died, so we know it will not happen again on every other board Byte is about to find.'),
  ('mission-vec-memory-and-storage-12', 2, 'tomas', 'Start where we started. What actually held that configuration across a reset, and rule out every kind of memory that cannot.'),
  ('mission-vec-memory-and-storage-12', 3, 'byte', 'The crash dump entry I pulled last mission gives us a real number, not a guess -- an erase-cycle count, and the rated limit for this sector from its own datasheet.'),
  ('mission-vec-memory-and-storage-12', 4, 'tomas', 'That is your proof. Not a corrupted read, not physical damage, not a bug in the code that reads it back -- flash exhaustion, plain and simple. A sector rewritten on every single pass, the same habit Byte already caught on the reactor telemetry service back in Act 5, except that time it consumed heap and this time it consumed a sector''s finite write-erase lifespan.'),
  ('mission-vec-memory-and-storage-12', 5, 'imani', 'Diagnose it properly, then propose the actual fix -- because firmware that finally remembers correctly is still firmware sitting on a bench. Getting it onto every live device safely is a different problem, and it is the next one waiting for us.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-memory-and-storage-01-o1', 'mission-vec-memory-and-storage-01', 1, 'Diagnose the incident', 'Judge what kind of memory the reactor arm''s gains and the door''s calibration actually needed in order to survive a reset.'),
  ('mission-vec-memory-and-storage-01-o2', 'mission-vec-memory-and-storage-01', 2, 'Define flash''s two operations', 'Match each flash term to its accurate definition.'),

  ('mission-vec-memory-and-storage-02-o1', 'mission-vec-memory-and-storage-02', 1, 'Explain why RAM cannot hold it', 'State why keeping the configuration in RAM alone fails to survive a reset.'),
  ('mission-vec-memory-and-storage-02-o2', 'mission-vec-memory-and-storage-02', 2, 'Read the reset evidence', 'Find the evidence proving RAM lost its values the instant power was cut.'),

  ('mission-vec-memory-and-storage-03-o1', 'mission-vec-memory-and-storage-03', 1, 'Tell EEPROM from flash', 'Choose the accurate distinction between EEPROM and flash erase granularity.'),

  ('mission-vec-memory-and-storage-04-o1', 'mission-vec-memory-and-storage-04', 1, 'Sort volatile from nonvolatile', 'Sort each memory type into volatile or nonvolatile.'),
  ('mission-vec-memory-and-storage-04-o2', 'mission-vec-memory-and-storage-04', 2, 'Confirm the board''s technology', 'Find the evidence identifying which nonvolatile technology this board actually uses.'),

  ('mission-vec-memory-and-storage-05-o1', 'mission-vec-memory-and-storage-05', 1, 'Explain the filesystem''s job', 'Choose the accurate description of what a filesystem layer adds over raw flash addresses.'),
  ('mission-vec-memory-and-storage-05-o2', 'mission-vec-memory-and-storage-05', 2, 'Spot the missing abstraction', 'Find the evidence proving this firmware writes directly to a fixed raw address with no filesystem layer at all.'),

  ('mission-vec-memory-and-storage-06-o1', 'mission-vec-memory-and-storage-06', 1, 'Define the endurance limit', 'Choose the accurate description of a flash sector''s write-erase cycle rating.'),
  ('mission-vec-memory-and-storage-06-o2', 'mission-vec-memory-and-storage-06', 2, 'Find the unbounded write', 'Find the evidence showing the configuration save fires on every main-loop pass rather than only on change.'),

  ('mission-vec-memory-and-storage-07-o1', 'mission-vec-memory-and-storage-07', 1, 'Order the ring buffer''s cycle', 'Order a ring buffer''s write cycle from first to last.'),
  ('mission-vec-memory-and-storage-07-o2', 'mission-vec-memory-and-storage-07', 2, 'Explain the flash-specific benefit', 'Choose the accurate reason a ring buffer pattern helps specifically with flash wear, not just memory size.'),

  ('mission-vec-memory-and-storage-08-o1', 'mission-vec-memory-and-storage-08', 1, 'Read the config layout', 'Find the evidence showing every save writes to the exact same fixed address.'),
  ('mission-vec-memory-and-storage-08-o2', 'mission-vec-memory-and-storage-08', 2, 'Judge the better save strategy', 'Choose the save strategy that actually respects the sector''s finite lifespan.'),

  ('mission-vec-memory-and-storage-09-o1', 'mission-vec-memory-and-storage-09', 1, 'Choose a wear-aware logging strategy', 'Choose the logging approach that respects flash endurance on a constrained device.'),
  ('mission-vec-memory-and-storage-09-o2', 'mission-vec-memory-and-storage-09', 2, 'Contrast the two write paths', 'Find the evidence proving the telemetry logger already writes in a bounded, rotating pattern unlike the configuration save.'),

  ('mission-vec-memory-and-storage-10-o1', 'mission-vec-memory-and-storage-10', 1, 'Order the boot sequence', 'Order this board''s boot sequence from power-on to running normally.'),

  ('mission-vec-memory-and-storage-11-o1', 'mission-vec-memory-and-storage-11', 1, 'Define a safe crash dump', 'Choose the accurate description of what a crash dump is and where it must be written.'),
  ('mission-vec-memory-and-storage-11-o2', 'mission-vec-memory-and-storage-11', 2, 'Read the last entry', 'Given the crash dump''s one recorded entry, judge what it reports about the failing write.'),

  ('mission-vec-memory-and-storage-12-o1', 'mission-vec-memory-and-storage-12', 1, 'Classify what actually holds the config', 'Find the evidence proving which storage type actually holds persistent configuration across a reset on this board.'),
  ('mission-vec-memory-and-storage-12-o2', 'mission-vec-memory-and-storage-12', 2, 'Prove the endurance limit was exceeded', 'Given the crash dump''s erase-cycle count and the sector''s rated limit, judge why the sector actually failed.'),
  ('mission-vec-memory-and-storage-12-o3', 'mission-vec-memory-and-storage-12', 3, 'Choose the real fix', 'Choose the fix that actually addresses a sector rewritten on every pass, not just its symptom.'),
  ('mission-vec-memory-and-storage-12-o4', 'mission-vec-memory-and-storage-12', 4, 'State the diagnosis', 'Having classified the storage, proven the endurance limit was exceeded, and chosen the real fix, state what actually happened to this board and what Vector Division must build next.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-memory-and-storage-01-o1-c1', 'mission-vec-memory-and-storage-01-o1', 1, 'multiple_choice', 'Both boards ran the same RTOS-based firmware. Only one lost its configuration on reset. What kind of memory must have been holding that configuration to explain the difference?', '{"question":"Both boards ran the same RTOS-based firmware. Only one lost its configuration on reset. What kind of memory must have been holding that configuration to explain the difference?","options":[{"id":"a","text":"RAM, since RAM is the fastest memory available"},{"id":"b","text":"Nonvolatile memory such as flash, the only kind that keeps its contents with no power applied at all"},{"id":"c","text":"CPU registers, since they hold the most recently used values"},{"id":"d","text":"It does not matter which memory type, any memory can survive a reset if the firmware is written correctly"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-memory-and-storage-01-o2-c1', 'mission-vec-memory-and-storage-01-o2', 1, 'drag_and_drop', 'Match each flash term to its accurate definition.', '{"items":[{"id":"i1","text":"Page"},{"id":"i2","text":"Sector"},{"id":"i3","text":"Program (write)"},{"id":"i4","text":"Erase"}],"targets":[{"id":"t1","label":"The smallest unit that can be written with new data"},{"id":"t2","label":"A larger region that must be erased as one unit, resetting all of its bits back to one"},{"id":"t3","label":"Writes new data into an already-erased page, only able to flip bits from one to zero"},{"id":"t4","label":"Resets an entire sector''s bits back to one so it can be written again"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),

  ('mission-vec-memory-and-storage-02-o1-c1', 'mission-vec-memory-and-storage-02-o1', 1, 'multiple_choice', 'Why does keeping the configuration only in RAM fail to survive a reset?', '{"question":"Why does keeping the configuration only in RAM fail to survive a reset?","options":[{"id":"a","text":"RAM is too slow to be trusted with important values"},{"id":"b","text":"RAM only holds its contents while it is powered -- cutting power, even briefly, erases everything in it with nothing left to recover"},{"id":"c","text":"RAM can only store a few bytes at a time"},{"id":"d","text":"RAM requires a filesystem before it can hold any values"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-memory-and-storage-02-o2-c1', 'mission-vec-memory-and-storage-02-o2', 1, 'investigation', 'Which evidence proves RAM lost its values the instant power was cut?', '{"evidence":[{"id":"e1","label":"Debug probe, pre-reset","detail":"Configuration values in RAM read correctly while the board is running"},{"id":"e2","label":"Debug probe, post-reset","detail":"The same RAM region reads only the power-on default pattern, with no trace of the prior configuration anywhere"},{"id":"e3","label":"Power log","detail":"Facility power draw stayed within normal range during the reset"}],"question":"Which evidence proves RAM lost its values the instant power was cut?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-memory-and-storage-03-o1-c1', 'mission-vec-memory-and-storage-03-o1', 1, 'multiple_choice', 'How does EEPROM''s erase granularity differ from flash''s?', '{"question":"How does EEPROM''s erase granularity differ from flash''s?","options":[{"id":"a","text":"They are identical, both always erase in large sectors"},{"id":"b","text":"EEPROM can erase and rewrite a single byte at a time; flash must erase an entire sector at once, even to change one bit within it"},{"id":"c","text":"EEPROM cannot be erased at all, only written once"},{"id":"d","text":"Flash can erase a single byte, EEPROM cannot erase at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-memory-and-storage-04-o1-c1', 'mission-vec-memory-and-storage-04-o1', 1, 'drag_and_drop', 'Sort each memory type into volatile or nonvolatile.', '{"items":[{"id":"m1","text":"RAM"},{"id":"m2","text":"CPU registers"},{"id":"m3","text":"Flash"},{"id":"m4","text":"EEPROM"}],"targets":[{"id":"volatile","label":"Volatile (needs continuous power)"},{"id":"nonvolatile","label":"Nonvolatile (keeps contents with no power)"}]}'::jsonb, '{"correctMapping":{"m1":"volatile","m2":"volatile","m3":"nonvolatile","m4":"nonvolatile"}}'::jsonb),
  ('mission-vec-memory-and-storage-04-o2-c1', 'mission-vec-memory-and-storage-04-o2', 1, 'investigation', 'Which evidence identifies which nonvolatile technology this board actually uses?', '{"evidence":[{"id":"e1","label":"Datasheet excerpt","detail":"The board''s persistent storage chip is listed as NOR flash, with a specified sector size and a rated write-erase cycle count"},{"id":"e2","label":"Bill of materials note","detail":"No separate EEPROM chip appears anywhere on the board''s component list"},{"id":"e3","label":"Physical note","detail":"The storage chip is soldered directly to the board rather than socketed"}],"question":"Which evidence identifies which nonvolatile technology this board actually uses?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-memory-and-storage-05-o1-c1', 'mission-vec-memory-and-storage-05-o1', 1, 'multiple_choice', 'What does a filesystem layer add on top of raw flash addresses?', '{"question":"What does a filesystem layer add on top of raw flash addresses?","options":[{"id":"a","text":"It makes the flash chip physically larger"},{"id":"b","text":"It turns raw addresses into named, trackable regions -- and can track which physical locations are free, used, or worn, instead of every caller hardcoding an address"},{"id":"c","text":"It removes the need to ever erase a sector"},{"id":"d","text":"It converts flash into volatile memory"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-memory-and-storage-05-o2-c1', 'mission-vec-memory-and-storage-05-o2', 1, 'investigation', 'Which evidence proves this firmware writes directly to a fixed raw address with no filesystem layer at all?', '{"evidence":[{"id":"e1","label":"Firmware source note","detail":"A hardcoded constant, CONFIG_ADDR = 0x08010000, is passed directly into every flash_write() call in the save routine"},{"id":"e2","label":"Build log","detail":"The firmware compiles cleanly with no warnings"},{"id":"e3","label":"Power log","detail":"The board draws power from a standard regulated supply"}],"question":"Which evidence proves this firmware writes directly to a fixed raw address with no filesystem layer at all?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-memory-and-storage-06-o1-c1', 'mission-vec-memory-and-storage-06-o1', 1, 'multiple_choice', 'What does a flash sector''s write-erase cycle rating actually describe?', '{"question":"What does a flash sector''s write-erase cycle rating actually describe?","options":[{"id":"a","text":"The maximum number of times the sector can be erased and rewritten before it can no longer reliably hold a charge"},{"id":"b","text":"The maximum clock speed the chip can run at"},{"id":"c","text":"The number of bytes the sector can store at once"},{"id":"d","text":"A marketing figure with no real physical basis"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-vec-memory-and-storage-06-o2-c1', 'mission-vec-memory-and-storage-06-o2', 1, 'investigation', 'Which evidence shows the configuration save fires on every main-loop pass rather than only on change?', '{"evidence":[{"id":"e1","label":"Firmware source snippet","detail":"save_config() is called unconditionally inside the main loop on every 10 millisecond tick, regardless of whether any value changed"},{"id":"e2","label":"Telemetry logger source snippet","detail":"The Act 11 logging task writes to a dedicated log region on a fixed schedule, unrelated to the configuration sector"},{"id":"e3","label":"Power log","detail":"Facility-wide power draw stayed within normal range throughout testing"}],"question":"Which evidence shows the configuration save fires on every main-loop pass rather than only on change?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-memory-and-storage-07-o1-c1', 'mission-vec-memory-and-storage-07-o1', 1, 'interactive_diagram', 'Order a ring buffer''s write cycle from first to last.', '{"diagramId":"ring-buffer-cycle","hotspots":[{"id":"write","label":"Write entry at head","explanation":"A new entry is written at the current head position."},{"id":"advance","label":"Advance the head pointer","explanation":"The head pointer moves forward to the next slot."},{"id":"wrap","label":"Wrap to the start","explanation":"If the head pointer reaches the end of the buffer, it wraps back to slot zero."},{"id":"overwrite","label":"Overwrite the oldest entry","explanation":"Once the buffer is full, the next write at the wrapped head position overwrites the oldest surviving entry."}],"task":"Order the steps of a ring buffer''s write cycle from first to last."}'::jsonb, '{"correctOrderIds":["write","advance","wrap","overwrite"]}'::jsonb),
  ('mission-vec-memory-and-storage-07-o2-c1', 'mission-vec-memory-and-storage-07-o2', 1, 'multiple_choice', 'Why does a ring buffer pattern help specifically with flash wear, not just memory size?', '{"question":"Why does a ring buffer pattern help specifically with flash wear, not just memory size?","options":[{"id":"a","text":"It does not help with wear at all, only with saving RAM"},{"id":"b","text":"Because each write lands on a new location before wrapping, wear is spread across several places instead of a single sector absorbing every write-erase cycle alone"},{"id":"c","text":"Ring buffers erase the flash chip''s wear rating entirely"},{"id":"d","text":"Ring buffers only work in RAM, never in flash"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-memory-and-storage-08-o1-c1', 'mission-vec-memory-and-storage-08-o1', 1, 'investigation', 'Which evidence shows every save writes to the exact same fixed address?', '{"evidence":[{"id":"e1","label":"Write log","detail":"Over 50,000 recorded configuration saves, every single one targeting address 0x08010000"},{"id":"e2","label":"Design note","detail":"The reserved configuration region is 4 kilobytes in total size"},{"id":"e3","label":"Power log","detail":"Supply voltage stayed within specification for every recorded save"}],"question":"Which evidence shows every save writes to the exact same fixed address?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-memory-and-storage-08-o2-c1', 'mission-vec-memory-and-storage-08-o2', 1, 'multiple_choice', 'Which save strategy actually respects the sector''s finite lifespan?', '{"question":"Which save strategy actually respects the sector''s finite lifespan?","options":[{"id":"a","text":"Save unconditionally on every main-loop pass, regardless of whether anything changed"},{"id":"b","text":"Save only when a value actually changes, and rotate writes across multiple slots in the reserved region instead of reusing one fixed address"},{"id":"c","text":"Save twice as often, to be safe"},{"id":"d","text":"Stop saving configuration entirely"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-memory-and-storage-09-o1-c1', 'mission-vec-memory-and-storage-09-o1', 1, 'multiple_choice', 'Which logging approach actually respects flash endurance on a constrained device?', '{"question":"Which logging approach actually respects flash endurance on a constrained device?","options":[{"id":"a","text":"Write a fresh log entry to the same fixed address on every tick, overwriting the previous one immediately"},{"id":"b","text":"Batch entries and write them in a circular pattern across a dedicated log region, treating flash endurance as a limited budget from the start"},{"id":"c","text":"Disable logging entirely to avoid any flash writes"},{"id":"d","text":"Log everything to a printed report only, never to flash"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-memory-and-storage-09-o2-c1', 'mission-vec-memory-and-storage-09-o2', 1, 'investigation', 'Which evidence proves the telemetry logger already writes in a bounded, rotating pattern unlike the configuration save?', '{"evidence":[{"id":"e1","label":"Telemetry logger source snippet","detail":"Log entries are written into a fixed-size circular buffer spanning several sectors, rotating to the next sector once the current one fills"},{"id":"e2","label":"Configuration save source snippet","detail":"Every save targets the single fixed address 0x08010000, with no rotation of any kind"},{"id":"e3","label":"Power log","detail":"Both routines draw power from the same regulated supply"}],"question":"Which evidence proves the telemetry logger already writes in a bounded, rotating pattern unlike the configuration save?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-memory-and-storage-10-o1-c1', 'mission-vec-memory-and-storage-10-o1', 1, 'interactive_diagram', 'Order this board''s boot sequence from power-on to running normally.', '{"diagramId":"boot-sequence","hotspots":[{"id":"poweron","label":"Power on","explanation":"The board''s hardware initializes and firmware begins executing."},{"id":"read","label":"Read the configuration sector","explanation":"The bootloader reads the reserved persistent configuration region."},{"id":"verify","label":"Verify the checksum","explanation":"A checksum over the read data confirms whether it is actually valid."},{"id":"decide","label":"Load or fall back","explanation":"A valid checksum loads the configuration; a failed one falls back to safe defaults instead of trusting garbage."}],"task":"Order the boot sequence steps from power-on to a decision about what configuration to trust."}'::jsonb, '{"correctOrderIds":["poweron","read","verify","decide"]}'::jsonb),

  ('mission-vec-memory-and-storage-11-o1-c1', 'mission-vec-memory-and-storage-11-o1', 1, 'multiple_choice', 'What is a crash dump, and where must it be written to be useful?', '{"question":"What is a crash dump, and where must it be written to be useful?","options":[{"id":"a","text":"A record of the device''s last known state, written to RAM so it can be read back quickly"},{"id":"b","text":"A record of exactly what the device was doing right before it failed, written to nonvolatile memory so it survives the reset that follows"},{"id":"c","text":"A printed error message shown on a display, never actually stored"},{"id":"d","text":"A backup copy of the entire firmware image"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-memory-and-storage-11-o2-c1', 'mission-vec-memory-and-storage-11-o2', 1, 'browser_simulation', 'Given the crash dump''s one recorded entry, what does it actually report about the failing write?', '{"screen":"CRASH DUMP -- REGION 0x0803F800 -- LAST ENTRY","question":"Given the crash dump''s one recorded entry, what does it actually report about the failing write?","records":[{"id":"r1","code":"BOOT_OK","detail":"Normal boot record from an earlier, successful startup"},{"id":"r2","code":"FLASH_ERR_WRITE_FAILED","detail":"flash_write() returned a write failure at address 0x08010000 during the configuration save, immediately before the reset that followed"},{"id":"r3","code":"POWER_NOMINAL","detail":"Supply voltage within specification at the time of the crash"},{"id":"r4","code":"SENSOR_HEARTBEAT","detail":"Position sensor responding normally at the time of the crash"}]}'::jsonb, '{"correctOptionId":"r2"}'::jsonb),

  ('mission-vec-memory-and-storage-12-o1-c1', 'mission-vec-memory-and-storage-12-o1', 1, 'investigation', 'Which evidence proves which storage type actually holds persistent configuration across a reset on this board?', '{"evidence":[{"id":"e1","label":"Debug probe, post-reset","detail":"RAM contains only the power-on default pattern after reset, no configuration data of any kind"},{"id":"e2","label":"Datasheet excerpt","detail":"The board''s persistent configuration region is located in onboard NOR flash, sector range 0x08010000 to 0x08011FFF"},{"id":"e3","label":"Bill of materials note","detail":"No separate EEPROM chip appears anywhere on the board''s component list"}],"question":"Which evidence proves which storage type actually holds persistent configuration across a reset on this board?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-vec-memory-and-storage-12-o2-c1', 'mission-vec-memory-and-storage-12-o2', 1, 'browser_simulation', 'Given the sector''s rated endurance and the crash dump''s measured erase-cycle count, why did the sector actually fail?', '{"screen":"FLASH DIAGNOSTIC -- SECTOR 0x08010000 -- FULL SWEEP","question":"Given the sector''s rated endurance and the crash dump''s measured erase-cycle count, why did the sector actually fail?","records":[{"id":"r1","code":"RATED_CYCLES=100000","detail":"Manufacturer datasheet rating for this sector''s write-erase endurance"},{"id":"r2","code":"MEASURED_CYCLES=1240000","detail":"Erase-cycle counter recovered from the crash dump region, over twelve times the rated endurance limit for this sector"},{"id":"r3","code":"PHYSICAL_INSPECTION=PASS","detail":"No physical damage, corrosion, or impact found on the board or chip package"},{"id":"r4","code":"READ_PATH_CHECKSUM=UNCHANGED","detail":"The firmware function that reads and validates the configuration has not been modified since the board was first deployed"}]}'::jsonb, '{"correctOptionId":"r2"}'::jsonb),
  ('mission-vec-memory-and-storage-12-o3-c1', 'mission-vec-memory-and-storage-12-o3', 1, 'multiple_choice', 'Which fix actually addresses a sector rewritten on every pass, rather than just its symptom?', '{"question":"Which fix actually addresses a sector rewritten on every pass, rather than just its symptom?","options":[{"id":"a","text":"Replace the chip with an identical part and change nothing about how it is written"},{"id":"b","text":"Move persistent-configuration writes to a bounded, rotating pattern -- write only on an actual change, and spread writes across multiple slots or sectors instead of rewriting the same fixed address every pass"},{"id":"c","text":"Request a higher endurance rating from the manufacturer for the existing chip"},{"id":"d","text":"Disable persistent configuration entirely so nothing is ever written"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-memory-and-storage-12-o4-c1', 'mission-vec-memory-and-storage-12-o4', 1, 'boss_encounter', 'Having classified the storage, proven the endurance limit was exceeded, and chosen the real fix, state what actually happened to this board.', '{"stages":[{"objectiveRef":"mission-vec-memory-and-storage-12-o1","label":"Classify what actually holds the config"},{"objectiveRef":"mission-vec-memory-and-storage-12-o2","label":"Prove the endurance limit was exceeded"},{"objectiveRef":"mission-vec-memory-and-storage-12-o3","label":"Choose the real fix"}],"task":"State the diagnosis in one sentence: the flash sector used for persistent configuration was rewritten far more times than its rated write-erase cycle ever allowed -- the same old firmware habit of writing on every pass, this time consuming a sector''s finite lifespan instead of the heap, and the fix is a bounded, rotating write pattern, not a replacement chip."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-memory-and-storage-12-o1","mission-vec-memory-and-storage-12-o2","mission-vec-memory-and-storage-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-memory-and-storage-01-o1-c1', 'orientation', 'Ask which memory type keeps its contents when power is removed entirely.', 10, 1),
  ('mission-vec-memory-and-storage-01-o1-c1', 'solution', 'Nonvolatile memory such as flash is the only kind built to hold its contents with no power applied at all -- that is what a reset requires of it.', 20, 2),
  ('mission-vec-memory-and-storage-01-o2-c1', 'orientation', 'Two terms describe a size of region, two describe an operation performed on it.', 10, 1),
  ('mission-vec-memory-and-storage-01-o2-c1', 'concept', 'A page is the small unit you can write into once it is already erased. A sector is the larger unit you must erase as a whole.', 20, 2),
  ('mission-vec-memory-and-storage-01-o2-c1', 'solution', 'Page: smallest writable unit. Sector: larger region erased as one unit. Program: writes into an erased page, flipping bits one to zero only. Erase: resets a whole sector''s bits back to one.', 30, 3),

  ('mission-vec-memory-and-storage-02-o1-c1', 'orientation', 'Ask what condition RAM needs to keep remembering anything at all.', 10, 1),
  ('mission-vec-memory-and-storage-02-o1-c1', 'solution', 'RAM only holds its contents while powered -- cutting power for even an instant erases everything in it, with nothing left to recover afterward.', 20, 2),
  ('mission-vec-memory-and-storage-02-o2-c1', 'orientation', 'Compare the same RAM region read before and after the reset.', 10, 1),
  ('mission-vec-memory-and-storage-02-o2-c1', 'solution', 'e2: after reset, that RAM region reads only the power-on default pattern -- no trace of the prior configuration survives.', 20, 2),

  ('mission-vec-memory-and-storage-03-o1-c1', 'orientation', 'Ask what the smallest unit each technology can erase actually is.', 10, 1),
  ('mission-vec-memory-and-storage-03-o1-c1', 'solution', 'EEPROM erases and rewrites a single byte at a time; flash must erase an entire sector at once, even to change just one bit within it.', 20, 2),

  ('mission-vec-memory-and-storage-04-o1-c1', 'orientation', 'Ask whether each type needs continuous power to keep its contents, or not.', 10, 1),
  ('mission-vec-memory-and-storage-04-o1-c1', 'solution', 'Volatile: RAM and CPU registers, both need continuous power. Nonvolatile: flash and EEPROM, both keep contents with no power at all.', 20, 2),
  ('mission-vec-memory-and-storage-04-o2-c1', 'orientation', 'Look for the source that names an actual technology, not just a physical or manufacturing detail.', 10, 1),
  ('mission-vec-memory-and-storage-04-o2-c1', 'solution', 'e1: the datasheet excerpt explicitly names NOR flash, with its sector size and rated write-erase cycle count.', 20, 2),

  ('mission-vec-memory-and-storage-05-o1-c1', 'orientation', 'A filesystem does not change what the flash physically is -- it changes what a caller has to know about it.', 10, 1),
  ('mission-vec-memory-and-storage-05-o1-c1', 'solution', 'A filesystem turns raw addresses into named, trackable regions, and can track which locations are free, used, or worn instead of every caller hardcoding an address.', 20, 2),
  ('mission-vec-memory-and-storage-05-o2-c1', 'orientation', 'Look for a source snippet showing an address used directly, rather than looked up through any abstraction.', 10, 1),
  ('mission-vec-memory-and-storage-05-o2-c1', 'solution', 'e1: a hardcoded CONFIG_ADDR constant is passed straight into every flash_write() call -- no filesystem layer sits between the firmware and the raw address.', 20, 2),

  ('mission-vec-memory-and-storage-06-o1-c1', 'orientation', 'The rating is about how many times something can happen, not how fast or how large.', 10, 1),
  ('mission-vec-memory-and-storage-06-o1-c1', 'solution', 'It is the maximum number of erase-and-rewrite cycles a sector can survive before it can no longer reliably hold a charge.', 20, 2),
  ('mission-vec-memory-and-storage-06-o2-c1', 'orientation', 'Compare the two source snippets -- one runs unconditionally, one runs on a schedule for a different purpose.', 10, 1),
  ('mission-vec-memory-and-storage-06-o2-c1', 'concept', 'Look specifically for a call with no condition guarding it, firing on every pass through the main loop regardless of whether anything changed.', 20, 2),
  ('mission-vec-memory-and-storage-06-o2-c1', 'solution', 'e1: save_config() is called unconditionally on every 10 millisecond tick, with no check for whether any value actually changed.', 30, 3),

  ('mission-vec-memory-and-storage-07-o1-c1', 'orientation', 'Nothing can advance before it is written, and nothing can wrap before it has advanced to the end.', 10, 1),
  ('mission-vec-memory-and-storage-07-o1-c1', 'solution', 'Write, then advance, then wrap once the end is reached, then overwrite the oldest entry once the buffer is full.', 20, 2),
  ('mission-vec-memory-and-storage-07-o2-c1', 'orientation', 'Think about what happens to a single fixed address if every write always lands on it, versus what happens if writes move around.', 10, 1),
  ('mission-vec-memory-and-storage-07-o2-c1', 'solution', 'Because each write lands on a new location before wrapping, wear is spread across several places instead of one sector absorbing every single cycle alone.', 20, 2),

  ('mission-vec-memory-and-storage-08-o1-c1', 'orientation', 'Look for a log that records where every save actually landed, not just the region''s total size.', 10, 1),
  ('mission-vec-memory-and-storage-08-o1-c1', 'solution', 'e1: over 50,000 recorded saves, every single one targeting the exact same address, 0x08010000.', 20, 2),
  ('mission-vec-memory-and-storage-08-o2-c1', 'orientation', 'The naive approach ignores two things: whether anything changed, and whether the address ever moves.', 10, 1),
  ('mission-vec-memory-and-storage-08-o2-c1', 'solution', 'Save only on an actual change, and rotate across multiple slots in the reserved region instead of reusing one fixed address every time.', 20, 2),

  ('mission-vec-memory-and-storage-09-o1-c1', 'orientation', 'Ask which approach treats the number of writes as a limited resource from the start.', 10, 1),
  ('mission-vec-memory-and-storage-09-o1-c1', 'solution', 'Batching entries and writing them in a circular pattern across a dedicated region treats flash endurance as a budget, rather than ignoring it.', 20, 2),
  ('mission-vec-memory-and-storage-09-o2-c1', 'orientation', 'Compare where each routine''s writes actually land -- a fixed single address, or a rotating set of them.', 10, 1),
  ('mission-vec-memory-and-storage-09-o2-c1', 'solution', 'e1: the telemetry logger writes into a fixed-size circular buffer across several sectors, rotating as each fills -- unlike the configuration save''s single fixed address.', 20, 2),

  ('mission-vec-memory-and-storage-10-o1-c1', 'orientation', 'Nothing can be verified before it is read, and nothing can be loaded before it is verified.', 10, 1),
  ('mission-vec-memory-and-storage-10-o1-c1', 'solution', 'Power on, then read the configuration sector, then verify its checksum, then load it or fall back to defaults depending on that result.', 20, 2),

  ('mission-vec-memory-and-storage-11-o1-c1', 'orientation', 'A crash dump has to outlive the very reset that follows the crash -- ask what kind of memory can do that.', 10, 1),
  ('mission-vec-memory-and-storage-11-o1-c1', 'solution', 'A crash dump records exactly what the device was doing right before it failed, and it must be written to nonvolatile memory to survive the reset that follows.', 20, 2),
  ('mission-vec-memory-and-storage-11-o2-c1', 'orientation', 'Three of the four records are routine status. Only one reports an actual failure at the moment of the crash.', 10, 1),
  ('mission-vec-memory-and-storage-11-o2-c1', 'solution', 'r2, FLASH_ERR_WRITE_FAILED, reports the write itself failing at address 0x08010000 right before the reset -- the others are unrelated boot, power and sensor status.', 20, 2),

  ('mission-vec-memory-and-storage-12-o1-c1', 'orientation', 'Rule out RAM first using what you already confirmed earlier this Act, then look for the source that actually names the technology.', 10, 1),
  ('mission-vec-memory-and-storage-12-o1-c1', 'solution', 'e2: the datasheet places persistent configuration in onboard NOR flash at a specific sector range -- that is what actually held it.', 20, 2),
  ('mission-vec-memory-and-storage-12-o2-c1', 'orientation', 'Compare the measured erase-cycle count against the rated limit, and rule out the other three records as distractors.', 10, 1),
  ('mission-vec-memory-and-storage-12-o2-c1', 'concept', 'Physical inspection passed and the read path is unchanged, so neither physical damage nor a software bug in reading explains the failure -- only the cycle count does.', 20, 2),
  ('mission-vec-memory-and-storage-12-o2-c1', 'solution', 'r2: 1,240,000 measured cycles against a 100,000 rated limit is over twelve times the sector''s endurance -- the sector failed from being rewritten far past its rated lifespan.', 30, 3),
  ('mission-vec-memory-and-storage-12-o3-c1', 'orientation', 'A working fix has to change how often and where writes land, not just what chip is installed.', 10, 1),
  ('mission-vec-memory-and-storage-12-o3-c1', 'solution', 'Write only on an actual change and rotate across multiple slots or sectors instead of the same fixed address every pass -- a replacement chip alone would simply wear out the same way again.', 20, 2),
  ('mission-vec-memory-and-storage-12-o4-c1', 'orientation', 'Combine all three findings into one sentence: what held the data, why it failed, and what actually fixes it.', 15, 1),
  ('mission-vec-memory-and-storage-12-o4-c1', 'solution', 'The flash sector used for persistent configuration was rewritten far more times than its rated write-erase cycle ever allowed -- the same old firmware habit of writing on every pass, this time consuming a sector''s finite lifespan instead of the heap, and the fix is a bounded, rotating write pattern, not a replacement chip.', 25, 2);
